CREATE TABLE admins(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,password TEXT NOT NULL,salt TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE admin_sessions(hash TEXT PRIMARY KEY,adminId TEXT NOT NULL REFERENCES admins(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE admin_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,adminId TEXT NOT NULL REFERENCES admins(id),action TEXT NOT NULL,target TEXT NOT NULL,details TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE report_actions(reportId TEXT PRIMARY KEY REFERENCES reports(id) ON DELETE CASCADE,adminId TEXT NOT NULL REFERENCES admins(id),resolution TEXT NOT NULL,notes TEXT NOT NULL,updatedAt TEXT NOT NULL);
CREATE TABLE user_restrictions(userId TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,restricted INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL,updatedAt TEXT NOT NULL);
CREATE TABLE content_moderation(targetType TEXT NOT NULL,targetId TEXT NOT NULL,hidden INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL,updatedAt TEXT NOT NULL,PRIMARY KEY(targetType,targetId));
ALTER TABLE interpretations ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
